import numpy as np
import domains
from docx_helper import Paper
from paper_common import *

I = 3


def build():
    r = load(I); E = r["extra"]; S = r["standard"]
    P = Paper("Surge-Aware Replanning for Hospital Capacity Control: Recency-Weighted Dynamic Programming and the Adaptation-Regret Frontier",
              "hospital capacity; Markov decision process; dynamic programming; Monte Carlo control; Q-learning; non-stationarity; replanning",
              running="Surge-aware replanning for hospital capacity", refdict=REFS)
    J = r["J_surge"]; V = r["variants"]; NEW = r["NEW"]
    st, pm_, so = V[0], V[2], V[3]
    i20, i80, i5 = NEW.index(20), NEW.index(80), NEW.index(5)
    om = r["omega"]
    P.abstract(
        "Hospital capacity decisions - admit, accelerate discharge, or divert - are sequential, uncertain and non-stationary: a policy tuned "
        "on last year's admissions can fail when demand surges. We study how a policy learned from logged data should be updated when only a few "
        "weeks of post-surge data exist. We model the daily decision as a Markov decision process, estimate it from logs, and compare dynamic "
        "programming (DP), first-visit Monte Carlo control and Q-learning, and we propose recency-weighted replanning: DP on a model whose counts "
        "from the new regime are up-weighted by a factor omega. A short precision-weighting argument gives a closed-form guide, omega* = 1 + N_old Δ² / σ². "
        f"On a stylised hospital simulator mirroring a Kaggle length-of-stay table (the Kaggle site was unreachable, so no real file was used), "
        f"learning does not beat a good occupancy rule under baseline demand: DP matches it (DP {S['DP']['J']:.1f} vs rule {S['Rule']['J']:.1f}), while Q-learning "
        f"({S['Q-learning']['J']:.1f}) and Monte Carlo ({S['Monte Carlo']['J']:.1f}) fall below it. Under a 30% demand surge, the baseline-trained policy collapses to {J[st]['mean'][0]:.1f} while a surge-trained oracle reaches "
        f"{r['oracle_surge']:.1f}. With 20 surge episodes, recency-weighted replanning recovers {J[pm_]['mean'][i20]:.1f} (+{r['static_vs_pooled10_20']['mean']:.1f}, "
        f"{pstr(r['static_vs_pooled10_20']['p'])}, uncorrected, 6 replicates), still far below the oracle, whereas training on the surge data alone does not help "
        f"({J[so]['mean'][i20]:.1f}, nominally worse than not adapting, not significant). The price is a measurable "
        f"regret under the original demand ({r['J_base'][st]['mean'][0] - r['J_base'][pm_]['mean'][i80]:.1f} points at 80 surge episodes). The results are a method study on simulated data, not clinical evidence.")

    # ------------------------------------------------------------------ 1
    P.h1("Introduction")
    P.p("A hospital manager makes a capacity decision every morning. Beds are occupied, a queue of patients waits for admission, and today's arrivals are "
        "uncertain. The manager may admit everyone the unit can hold, accelerate some discharges to free beds, or divert incoming ambulances to a neighbouring "
        "hospital. Each choice changes tomorrow's occupancy and queue, so the problem is sequential. It is also non-stationary: respiratory seasons, epidemics, "
        "holidays and local events change arrival rates from one month to the next. A policy that is excellent in a stable regime can be badly mismatched in the "
        "next one, and the data that would re-tune it - post-change days - are scarce precisely when they matter most.")
    P.p("Markov decision processes (MDPs) are the natural language for such decisions [@puterman,sb], and reinforcement learning has been applied to many clinical "
        "and operational problems [@yu,gottesman]. Hospitals, however, do not experiment; they log the consequences of their existing practice. This is the offline "
        "setting, in which a model or value function is learned from data generated by a different (behaviour) policy and in which distribution shift is the central "
        "difficulty [@levine]. Three questions follow. First, if one estimates an MDP from logged operations, how much does planning on it - by dynamic programming "
        "(DP) - or learning on it - by Monte Carlo (MC) control or Q-learning - actually improve on a sensible occupancy rule? Second, what happens when demand shifts after "
        "deployment? Third, given only a few post-shift weeks, how should old and new data be combined?")
    P.p("**Contributions.** (i) We formulate daily capacity control as a 490-state, 3-action MDP and benchmark DP, MC and Q-learning on it with exact, "
        "simulator-based scoring. (ii) We propose **recency-weighted replanning**: weighted maximum-likelihood counts followed by DP, a one-parameter family "
        "that interpolates between 'ignore the new data' and 'use only the new data'. (iii) We give a precision-weighting argument that yields a closed-form "
        "guide omega* = 1 + N_old Δ² / σ² for the weight. (iv) We map the **adaptation-regret frontier**: how much return is gained under the surge versus lost "
        "if demand returns to normal. (v) We report honest negative results: at baseline demand learning does not beat a good rule, MC is unstable, and "
        "re-estimating from the few surge episodes alone does not beat doing nothing (it is nominally worse, but the difference is not significant), and even the best adaptation recovers only a minority of the gap to a surge-trained oracle.")
    P.p("**Scope and honesty.** The Kaggle site could not be reached from the build environment, so the 'dataset' is a transparent hospital simulator whose recorded "
        "variables (admissions, occupancy, queue, discharges) mirror those of public length-of-stay tables. All claims concern the behaviour of the algorithms, not "
        "any real hospital.")

    # ------------------------------------------------------------------ 2
    P.h1("Related work")
    P.p("**Healthcare operations as MDPs.** Dynamic programming has long been used for sequential decisions in health care, from treatment timing to resource allocation "
        "[@schaefer,puterman]. Appointment and capacity problems in particular are classical applications of stochastic optimisation [@gupta]. Our contribution is not a new "
        "operations model but a study of what happens when such a model must be learned from logs and then re-learned after a regime change.")
    P.p("**Reinforcement learning in health.** Surveys document the growth of RL in clinical decision support and its pitfalls, notably evaluation without a simulator and "
        "distribution shift [@yu,gottesman]. Landmark applications such as sepsis treatment policies [@komorowski] illustrate how a tabular MDP estimated from "
        "records can yield interpretable policies; they also illustrate why careful off-policy evaluation matters. Here the simulator supplies exact evaluation, which "
        "isolates algorithmic behaviour from evaluation error.")
    P.p("**Offline RL and pessimism.** When data are logged by another policy, value estimates for poorly covered actions are unreliable and are routinely exploited by the "
        "optimiser. Remedies include constraining the policy to the data's support [@fujimoto] and penalising uncertain values [@kumar,jin]. We use the simplest member of this "
        "family, a count threshold, and show that it interacts decisively with adaptation: thin new-regime data fall below the threshold.")
    P.p("**Adapting to change.** Combining a large old sample with a small new sample is an instance of precision weighting, the same logic that underlies shrinkage "
        "estimators [@efron]. We make it explicit for the transition counts of an MDP and test it against exact ground truth.")

    background(P)

    # ------------------------------------------------------------------ problem
    P.h1("Problem formulation: daily capacity control")
    P.p("The simulator represents a 40-bed unit. Each day the following happens in order: arrivals are drawn from a Poisson distribution whose mean depends on the weekday "
        "(9.5, 9.0, 8.5, 8.5, 9.0, 7.0, 6.5 patients, Monday to Sunday) multiplied by a demand factor; if the action is *divert*, half of the arrivals are sent elsewhere; the rest "
        "join a queue (capped at 15, with overflow lost); patients are admitted while beds are free; and each occupied bed is vacated with probability 0.20 (0.28 under "
        "*early-discharge*). The decision maker observes only a coarse summary.")
    P.table([["Element", "Definition"],
             ["State (490)", "weekday (7) × occupancy bucket, 3 beds wide (14) × queue band {0, 1-2, 3-5, 6-9, 10+} (5)"],
             ["Actions (3)", "admit; early-discharge (accelerate discharges); divert (turn away about half of arrivals)"],
             ["Reward", "+1 per admission − 0.3 per queued patient − 5 per overflow − 2 per diverted patient − 1.6 per excess early discharge"],
             ["Discount, horizon", "γ = 0.97; episodes of 28 days"],
             ["Behaviour policy", "occupancy rule (divert if ≥35 beds and queue ≥3; early-discharge if ≥30 beds; otherwise admit), randomised with ε = 0.25"],
             ["Dataset mirrored", "Hospital length-of-stay / healthcare-analytics tables on Kaggle (admissions, occupancy, stay length)"]],
            "The capacity-control MDP.", widths=[3.4, 13.0])
    P.p("The reward encodes the usual tension. Admitting patients earns throughput; keeping them waiting, losing them to overflow or sending them away costs; and "
        "pushing patients out early frees beds but is penalised because it raises the risk of bounce-backs. Because the occupancy rule is hand-built and sensible, there is "
        "limited room for improvement at baseline demand, which makes the question of what learning adds a fair one rather than a foregone conclusion.")

    # ------------------------------------------------------------------ method
    P.h1("Method: recency-weighted replanning")
    P.p("Let D_old be the logged transitions from the baseline regime (here 800 episodes, 22,400 days) and D_new the transitions observed after the surge. For a "
        "weight ω ≥ 0 the weighted counts and mean rewards are")
    P.eq("N_ω(s,a,s') = N_old(s,a,s') + ω N_new(s,a,s'),      R̂_ω(s,a) = [ Σ_old r + ω Σ_new r ] / [ N_old(s,a) + ω N_new(s,a) ]", "3")
    P.p("and the replanned policy is obtained by DP on (P̂_ω, R̂_ω), with the support constraint applied to the weighted count. ω = 0 ignores the new data (the *static* policy), ω = 1 "
        "pools the data naively, and ω → ∞ approaches estimation from the new data alone. No parameters of any network are retrained, which makes the procedure cheap "
        "enough to rerun every day.")
    P.h2("A precision-weighting guide for ω")
    P.p("Consider a single transition probability. Under the old regime its true value is p_o, under the new regime p_n = p_o + Δ, and a Bernoulli observation has variance σ² "
        "(at most 1/4). The pooled estimator is p̂ = q p̂_o + (1 − q) p̂_n with q = N_old / (N_old + ω N_new). Relative to the *new* regime its bias is −qΔ and its variance is "
        "approximately q² σ²/N_old + (1 − q)² σ²/N_new, so")
    P.eq("MSE(q) = q² Δ² + q² σ²/N_old + (1 − q)² σ²/N_new.", "4")
    P.p("Setting the derivative to zero gives q* = (σ²/N_new) / (Δ² + σ²/N_old + σ²/N_new), and converting q* back to a weight yields")
    P.eq("ω* = 1 + N_old Δ² / σ².", "5")
    P.p("Two features deserve emphasis. The weight grows with the amount of old data: the more evidence the old regime carries, the harder the new data must be "
        "up-weighted to overrule it. It also grows with the squared size of the shift. If nothing has changed (Δ = 0) the guide returns ω* = 1, i.e. plain pooling. In practice "
        "Δ is unknown and differs across state-action pairs, so ω is treated as a single tunable constant and Eq. (5) is used only to indicate its order of magnitude: with, "
        "say, N_old = 50 observations of a state-action pair, σ² = 0.25 and a 10-point shift, ω* ≈ 3; with 200 observations ω* ≈ 9.")
    P.code("""Algorithm 1  Recency-weighted replanning
input: old logs D_old, new logs D_new, weight omega, support threshold n_min
1:  for each logged transition (s,a,r,s') with weight w = 1 (old) or omega (new):
2:      N[s,a,s'] += w ;  Rsum[s,a] += w * r
3:  n[s,a] = sum_s' N[s,a,s']
4:  for (s,a) with n[s,a] >= n_min:  P[s,a,.] = (N[s,a,.] + pseudo-absorption) / (n[s,a] + 1);  R[s,a] = Rsum / (n+1)
5:  for (s,a) with n[s,a] <  n_min:  complete pessimistically (absorb with worst observed reward)
6:  pi <- value_iteration(P, R, gamma);  in unsupported states use the clinician's modal action
7:  return pi""")

    # ------------------------------------------------------------------ protocol
    protocol(P, [["Item", "Setting"],
                 ["Simulator", "40-bed unit, Poisson arrivals with weekday profile, 28-day episodes"],
                 ["States / actions", "490 / 3 (weekday × occupancy bucket × queue band)"],
                 ["Logged baseline data", "800 episodes (22,400 transitions) from the ε-noisy occupancy rule"],
                 ["Oracle model", "6,000 baseline episodes (for exact learning-curve scoring)"],
                 ["Stage 1 (baseline)", "5 replicates; 300 evaluation episodes per policy"],
                 ["Stage 2 (surge)", "demand × 1.3; 0, 5, 10, 20, 40, 80 surge episodes from the same behaviour rule; 6 replicates; 200 evaluation episodes"],
                 ["Stage 3 (ω sweep)", "ω in {1, 3, 10, 30, 100}; 10, 20, 40 surge episodes; both regimes scored"],
                 ["Surge-trained oracle", "DP on 6,000 surge episodes"]],
             150000, 5, 300,
             extra="Four replanning variants are compared in Stage 2: **Static** (baseline data only), **Pooled, equal weight** (ω = 1), **Pooled, recency ×10** (ω = 10) and "
                   "**Surge data only** (ω → ∞ with the baseline data removed).")

    # ------------------------------------------------------------------ results
    P.h1("Results")
    P.h2("Baseline demand: learning does not beat a good rule")
    rows_b = std_rows(S, ("admitted", "overflow", "diverted", "early_dc"), ("Admitted", "Overflow", "Diverted", "Early d/c"))
    rows_b = [[c.replace("(10x data)", "(7.5x data)") for c in row] for row in rows_b]
    t_base = P.table(rows_b,
            "Baseline demand. Discounted return over a 28-day episode and mean episode counts (5 replicates; true simulator).", widths=[5.4, 3.4, 1.8, 1.8, 1.8, 1.8], font=8.5)
    P.p(f"Table {t_base} shows that planning on the estimated MDP essentially reproduces the occupancy rule: DP scores {S['DP']['J']:.1f} ± {S['DP']['ci']:.1f} against "
        f"{S['Rule']['J']:.1f} for the rule, and even the oracle DP (7.5 times more data) scores {S['Oracle DP']['J']:.1f}. This is not a failure of the solver - the DP and policy-iteration "
        f"solutions agreed in every replicate - but a property of the problem: the rule was written by someone who understood it, so a policy that is optimal for the estimated, "
        f"state-aggregated model has little left to find. Q-learning is below the rule ({S['Q-learning']['J']:.1f} ± {S['Q-learning']['ci']:.1f}). Monte Carlo is clearly worse "
        f"({S['Monte Carlo']['J']:.1f} ± {S['Monte Carlo']['ci']:.1f}); its policies divert about {S['Monte Carlo']['info']['diverted']:.1f} patients per episode against "
        f"{S['Rule']['info']['diverted']:.1f} for the rule, presumably because diversion has a high-variance, rarely-observed outcome that the episode-level returns estimate noisily.")
    f_learn = P.fig(fig(I, "fig_learning"), "Learning curves on the oracle MDP (mean ± s.d. over 5 replicates). Q-learning rises within about 10,000 steps and plateaus below the DP optimum "
          "(dashed); Monte Carlo plateaus lower and wider.", 10.5)
    P.p(f"Figure {f_learn} explains the ranking. Q-learning's bootstrapping spreads reward information through the 490-state chain quickly; MC must wait for entire 28-day episodes and "
        f"averages a long, noisy return into every update, so its plateau is both lower and more variable between replicates. Neither method reaches the DP optimum on the oracle MDP (Q-learning plateaus near 72 and Monte Carlo near 63, against 81 for the oracle DP and 78 for the rule); both "
        f"learn from the same finite log that DP uses, and here the price of not solving the model exactly is not small. {learning_sentence(E)}")
    P.fig(fig(I, "fig_bars"), "True-simulator return by method under baseline demand (error bars: 95% CI over replicates).", 10.0)
    P.fig(fig(I, "fig_policies"), "Action chosen by each method in every state observed in the oracle data (colours: admit / early-discharge / divert). The learned policies "
          "DP and Q-learning largely reproduce the behaviour rule; Monte Carlo and the oracle DP deviate in scattered states, Monte Carlo including many low-occupancy ones.", 12.5)

    P.h2("Demand surge: every baseline-trained policy fails")
    P.p(f"We now raise arrivals by 30% without changing anything else. Table {P.ntab + 1} (below) shows that a policy trained on baseline data - or the occupancy rule itself - collapses: "
        f"the static policy's return falls from {r['J_base'][st]['mean'][0]:.1f} (baseline) to {J[st]['mean'][0]:.1f} ± {J[st]['ci'][0]:.1f} under surge, and the rule scores "
        f"{r['rule_surge']:.1f}. A policy trained on an abundance of surge data (6,000 episodes) obtains {r['oracle_surge']:.1f}. The gap of about {r['oracle_surge'] - J[st]['mean'][0]:.0f} points "
        f"is the value of knowing the regime; it is also an upper bound on what any adaptation scheme can recover from a few weeks of data.")
    rows = [["Surge episodes"] + [str(n) for n in NEW]]
    for v in V:
        rows.append([v] + [pm(J[v]["mean"][i], J[v]["ci"][i], 1) for i in range(len(NEW))])
    P.table(rows, "Return under the +30% surge, by replanning variant and number of surge episodes available (mean ± 95% CI, 6 replicates). "
            f"Surge-trained oracle: {r['oracle_surge']:.1f}; occupancy rule: {r['rule_surge']:.1f}.", widths=[3.6, 2.1, 2.1, 2.1, 2.1, 2.1, 2.1], font=7.5)

    P.h2("Adaptation: how much surge data, and how to use it")
    f_ad = P.fig(fig(I, "fig_adaptation"), "Return under surge as surge episodes accumulate. Recency-weighted pooling (ω = 10) improves with more data, though noisily; equal-weight pooling "
          "needs many more episodes; using surge data alone does not help (nominally below the static policy). Error bars: 95% CI over 6 replicates.", 11.0)
    P.p(f"Figure {f_ad} is the central result. Four observations follow. (1) **Recency weighting works.** With ω = 10 the return improves from {J[st]['mean'][0]:.1f} to {J[pm_]['mean'][i5]:.1f} after only "
        f"5 surge episodes (140 days) and to {J[pm_]['mean'][i20]:.1f} after 20; at 20 episodes the improvement over the static policy is {r['static_vs_pooled10_20']['mean']:.1f} ± "
        f"{r['static_vs_pooled10_20']['ci']:.1f} ({pstr(r['static_vs_pooled10_20']['p'])}, paired over replicates). At 80 episodes it reaches {J[pm_]['mean'][i80]:.1f}, "
        f"although the confidence interval (± {J[pm_]['ci'][i80]:.1f}) is wide. (2) **Equal-weight pooling is slow.** The 800 baseline episodes swamp the new data; "
        f"with ω = 1 nothing changes until 40 episodes ({J[V[1]]['mean'][NEW.index(40)]:.1f}) and the return is still {J[V[1]]['mean'][i80]:.1f} at 80. (3) **Surge data alone does not help.** "
        f"With ω → ∞ and the old data removed, the return is {J[so]['mean'][i5]:.1f} at 5 episodes and {J[so]['mean'][i80]:.1f} at 80, nominally below the static policy ({J[st]['mean'][0]:.1f}); "
        f"the paired difference at 20 episodes is {r['surgeonly_vs_static_20']['mean']:.1f} ± {r['surgeonly_vs_static_20']['ci']:.1f} ({pstr(r['surgeonly_vs_static_20']['p'])}), so we cannot call it harmful, only not helpful. At 5 episodes the "
        f"recency-weighted variant beats it by {r['pooled10_vs_surgeonly_5']['mean']:.1f} ± {r['pooled10_vs_surgeonly_5']['ci']:.1f} ({pstr(r['pooled10_vs_surgeonly_5']['p'])}). "
        f"The surge-only return is identical across replicates at 5, 10 and 20 episodes (zero spread), which suggests that the support threshold leaves almost all of the 1,470 state-action pairs "
        f"unsupported so that the policy falls back to the clinician rule (we did not verify this directly); its baseline return is also not reduced ({r['J_base'][so]['mean'][i80]:.1f}), consistent with that reading. (4) **The remaining gap is large.** Even at 80 episodes, adaptation recovers only about "
        f"{100*(J[pm_]['mean'][i80]-J[st]['mean'][0])/(r['oracle_surge'] - J[st]['mean'][0]):.0f}% of the {r['oracle_surge'] - J[st]['mean'][0]:.0f}-point gap to the oracle (and about {100*(J[pm_]['mean'][i20]-J[st]['mean'][0])/(r['oracle_surge'] - J[st]['mean'][0]):.0f}% at 20 episodes); the oracle used 75 times more surge data.")
    f_reg = P.fig(fig(I, "fig_regret"), "Regret check: return under the original demand for the same policies. Recency-weighted replanning gives up some baseline performance as it forgets the old regime.", 9.5)
    P.p(f"Figure {f_reg} shows the price of adapting. If demand returns to normal, the recency-weighted policy built from 80 surge episodes scores {r['J_base'][pm_]['mean'][i80]:.1f} instead of "
        f"{r['J_base'][st]['mean'][0]:.1f}, a regret of {r['J_base'][st]['mean'][0] - r['J_base'][pm_]['mean'][i80]:.1f}. Equal-weight pooling loses less "
        f"({r['J_base'][V[1]]['mean'][i80]:.1f}), which is the mirror image of its slower adaptation, and surge-only replanning loses nothing here. The regret curves have no error bars (means of 6 replicates). The two figures together define a frontier: more weight on new data buys return under the surge and costs return in the old regime.")

    P.h2("The adaptation-regret frontier")
    rows = [["ω"] + [f"{n} episodes: surge / baseline" for n in r["NN"]]]
    for w in r["OM"]:
        rows.append([str(w)] + [f"{om[str(n)][str(w)]['surge'] + 0.0:.1f} / {om[str(n)][str(w)]['base']:.1f}".replace("-0.0 /", "0.0 /") for n in r["NN"]])
    P.table(rows, "Recency-weight sweep: return under surge / return under baseline demand (6 replicates).", widths=[2.0, 4.8, 4.8, 4.8], font=8.5)
    f_om = P.fig(fig(I, "fig_omega"), "Left: surge return versus the recency weight ω for 10, 20 and 40 surge episodes. Right: the same points traced on the surge-versus-baseline plane; moving "
          "right-to-left along a curve trades baseline return for surge return.", 13.0)
    best = {n: max(r["OM"], key=lambda w: om[str(n)][str(w)]["surge"]) for n in r["NN"]}
    P.p(f"Figure {f_om} shows that the surge return rises with ω and then saturates or declines, while baseline return falls monotonically. "
        + " ".join(f"With {n} surge episodes the best surge return ({om[str(n)][str(best[n])]['surge']:.1f}".replace("-0.0", "0.0") + f") is obtained at ω = {best[n]}." for n in r["NN"])
        + " The differences among ω = 10, 30 and 100 are small relative to the confidence intervals (several intervals span 5 points or more), so the location of the optimum is not resolved; "
          "what is resolved is that ω = 1 is clearly worse than ω ≥ 3 at 40 episodes (nominally also at 20, where the intervals overlap) and that baseline return keeps falling as ω grows."
        + " The closed-form guide in Eq. (5) predicts that the optimal weight should be of order one to a few tens for the per-cell counts in this problem, which is roughly consistent in order of magnitude "
          "with the sweep (the sweep favours somewhat larger values than the worked examples of Eq. (5)); because the shift Δ differs between cells, the sweep is a more reliable guide than the formula, which should be read as an explanation of the trend "
          "(heavier weight on new data when the old sample is large or the shift is big) rather than as a prescription.")

    # ------------------------------------------------------------------ discussion
    P.h1("Discussion")
    P.p("**What a hospital would take from this.** If the occupancy rule is already sensible, learning a policy from logs buys little in stable times; the benefit appears "
        "when the world changes. In that case the cheapest effective action is not to relearn from scratch but to keep the large historical model and up-weight the "
        "recent weeks. Relearning only from recent data is the intuitive response; in this simulator it gave no benefit when the recent sample was small.")
    P.p("**DP, MC and Q-learning.** DP is the reference: when a model is estimated it is exact and fast (fast for 1,470 state-action pairs). Q-learning approaches it "
        "from experience alone and is the better of the two model-free methods here. Monte Carlo's weakness is structural. It averages complete returns, so rare, high-variance "
        "events (diversions, overflows) contaminate every state on the path; with 28-day episodes this variance dominates. The practical lesson is that for long-horizon "
        "operational problems with sparse costly events, bootstrapping methods are preferable to episode-return averaging unless many more samples are available.")
    P.p("**Why surge-only does not help.** Our reading, not directly tested here, is that this is a support effect. A threshold on the number of observations per "
        "state-action pair is a sensible safeguard against exploiting noise, but it means that estimates built from a few weeks of data cover very little of the state "
        "space. The recency-weighted variant avoids this because the large historical count keeps most cells supported while the weight lets the new regime dominate the "
        "cells where it has spoken. The advantage over surge-only at 5 episodes was significant in a paired test, but this is one simulator with six replicates.")
    P.p("**Choosing ω.** The frontier suggests an operational rule: choose ω in the range where surge return has plateaued (here about 10 to 30) and no larger, since beyond it the surge return does not improve while the baseline regret keeps growing. Because the regret is incurred only if "
        "demand returns to normal, a hospital that expects the surge to persist (an epidemic season) can accept the upper end of that range, and one that expects it to be transient should "
        "choose a smaller one. A natural extension is to detect the regime change and set ω from the detected shift size using Eq. (5).")
    limitations(P, [
        "**Uniform surge.** The surge multiplies all arrival rates by 1.3 and leaves length of stay unchanged. Real surges change case mix, and therefore the discharge process, as well.",
        "**Replanning data come from the old rule.** The surge episodes are generated by the baseline occupancy rule, so exploration of surge-appropriate actions is thin. Active data collection could change the conclusions.",
        "**One weight for all cells.** Eq. (5) says the optimal weight varies across state-action pairs; a single global ω is a simplification.",
        "**Small replicate counts.** Six replicates keep the computation modest; several intervals are wide (for example at 80 surge episodes) and differences between ω values near the optimum are not statistically resolved.",
    ])
    ethics_future(P, "(1) Sweep the support threshold and the surge size, and use more replicates so that the omega comparisons near the optimum can be resolved; "
                  "(2) detect the regime change online and set omega from the estimated shift using Eq. (5); (3) collect surge-appropriate exploratory data actively; "
                  "(4) run the adapter on a real admissions log and compare model-based estimates with a held-out period.")
    P.h1("Conclusion")
    P.p(f"On a hospital-capacity MDP, model-based learning from logs (DP) matches a good occupancy rule at baseline demand and model-free learners fall below it, and none protects against a surge: the baseline-trained policy "
        f"(like the rule itself) falls to {J[st]['mean'][0]:.1f} against {r['oracle_surge']:.1f} for a surge-trained oracle. Recency-weighted replanning - DP on counts that up-weight recent data - improves "
        f"on the static policy with a few weeks of post-surge logs ({J[pm_]['mean'][i20]:.1f} after 20 episodes, {pstr(r['static_vs_pooled10_20']['p'])} versus static) but closes only a minority "
        f"of the gap to the oracle, while using the surge data alone gave no benefit. The adaptation-regret frontier makes the trade-off explicit. All results are from a simulator, so the contribution is a tested "
        f"recipe and a set of measured trade-offs, to be re-examined on real admission logs with the accompanying adapter.")

    defense(P, [
        ("Why does DP not beat the occupancy rule at baseline demand?",
         f"Because the rule is already near-optimal for the discretised problem. Oracle DP, with 7.5 times more data, scores {S['Oracle DP']['J']:.1f} against {S['Rule']['J']:.1f} for the rule. The honest "
         "conclusion is that learning adds little in a stable regime; its value shows up under change."),
        ("Is a 30% surge realistic, and does the conclusion depend on it?",
         "Surges of this order are plausible for seasonal peaks, but the number is a stress-test parameter, not an estimate. The qualitative conclusions (static policies fail, recency "
         "weighting helps, surge-only does not) rely on the surge being large enough to change the optimal action in some states; we expect, but did not test, that a smaller surge would shrink the gaps."),
        ("Why not simply retrain on the new data?",
         f"That is the surge-only variant, and it did not beat not adapting ({J[so]['mean'][i20]:.1f} versus {J[st]['mean'][i20]:.1f} at 20 episodes; {pstr(r['surgeonly_vs_static_20']['p'])} for the difference), probably because thin data leave most state-action pairs unsupported."),
        ("Could the results be an artefact of the support threshold?",
         "The threshold determines how much of the model is trusted, so it matters for the surge-only variant. It is a standard offline-RL safeguard rather than a tuned "
         "parameter, and the main conclusion (old data must be retained) is the same direction as the pessimism literature [@kumar,jin]. A sensitivity sweep of the threshold is the obvious extension and is easy to run with the code provided."),
        ("What is needed to run this on the real Kaggle file?",
         "Map the table to (day, occupancy, queue, action, reward) rows, discretise with the same bins, and call kaggle_adapter.transitions_from_dataframe. Because a real file has no simulator, "
         "report model-based value estimates on held-out days and label them as estimates."),
    ])
    repro(P, 3, ["fig_learning", "fig_bars", "fig_policies", "fig_agreement", "fig_adaptation", "fig_regret", "fig_omega"])
    code_appendix(P, 3, [domains.Hospital])
    rl_core_appendix(P)
    P.refs()
    path = f"{PAP}/Paper03_Hospital_Surge_Replanning.docx"
    P.save(path)
    return path


